     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	import java.util.List;
     9	
    10	/**
    11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    13	 * (half-even) at every step.
    14	 */
    15	public final class PriceCalculator {
    16	
    17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.25");
    18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    19	
    20	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    21	        int nights = 0;
    22	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    23	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    24	            subtotal = subtotal.add(nightPrice(room, night));
    25	            nights++;
    26	        }
    27	        BigDecimal discount = switch (ratePlan) {
    28	            case STANDARD -> cents(BigDecimal.ZERO);
    29	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    30	        };
    31	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    32	    }
    33	
    34	    BigDecimal nightPrice(Room room, LocalDate night) {
    35	        BigDecimal nightlyRate = room.nightlyRate();
    36	        if (isHighSeason(night)) {
    37	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    38	        }
    39	        return cents(nightlyRate);
    40	    }
    41	
    42	    /** Easter weeks (nights from Palm Sunday to Easter Sunday, both included); only the years listed. */
    43	    private static final List<EasterWeek> EASTER_WEEKS = List.of(
    44	            new EasterWeek(LocalDate.of(2027, 3, 21), LocalDate.of(2027, 3, 28)),
    45	            new EasterWeek(LocalDate.of(2028, 4, 9), LocalDate.of(2028, 4, 16)));
    46	
    47	    private record EasterWeek(LocalDate first, LocalDate last) {
    48	        boolean contains(LocalDate date) {
    49	            return !date.isBefore(first) && !date.isAfter(last);
    50	        }
    51	    }
    52	
    53	    /**
    54	     * High season: from December 15 to the end of February, the whole of July, and the Easter week.
    55	     */
    56	    static boolean isHighSeason(LocalDate date) {
    57	        Month month = date.getMonth();
    58	        return EASTER_WEEKS.stream().anyMatch(week -> week.contains(date))
    59	                || month == Month.JANUARY
    60	                || month == Month.FEBRUARY
    61	                || month == Month.JULY
    62	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    63	    }
    64	
    65	    static BigDecimal cents(BigDecimal value) {
    66	        return value.setScale(2, RoundingMode.HALF_EVEN);
    67	    }
    68	}
